# PUT /api/sheets/{sheetId}/claims/{claimId}/status — change a claim's status by an action: open
# (DRAFT to OPEN), settle (OPEN to SETTLED, or to PENDING when a clerk settles a claim whose due is above the sheet's
# clerk limit), approve (PENDING to SETTLED) or reject with a reason (PENDING back to OPEN), both by a steward, or void
# (DRAFT, OPEN or PENDING to VOID), or resettle by a steward (SETTLED again, its due fixed anew at today's figure as
# an open claim bound by no statement). An action the claim's status does not allow, a claim dated inside a closed period,
# settling or approving by the user who opened the claim, settling or approving a claim with no proofs whose due is above
# the proof threshold in force on its date (checked before the clerk limit), approving, rejecting or re-settling by a clerk, a rejection without a
# reason, or an unknown action, is a 409 and a claim not on the sheet a 404, neither writing anything. Opening gives
# the claim the sheet's next number and records who opened it; a voided claim keeps its number. Responds with the
# claim as stored.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimStatus
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimStatusChanged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the action is open, settle, approve, reject (which needs a reason), void or resettle. */
public class ValidateClaimStatus {
    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatusChange> change)
            throws InvalidClaimStatusException {
        String action = request == null || request.action() == null ? "" : request.action().trim();
        ClaimAction taken = switch (action) {
            case "open" -> ClaimAction.OPEN;
            case "settle" -> ClaimAction.SETTLE;
            case "approve" -> ClaimAction.APPROVE;
            case "reject" -> ClaimAction.REJECT;
            case "void" -> ClaimAction.VOID;
            case "resettle" -> ClaimAction.RESETTLE;
            default -> throw new InvalidClaimStatusException("The action must be open, settle, approve, reject, void or resettle");
        };
        ClaimStatus to = switch (taken) {
            case OPEN, REJECT -> ClaimStatus.OPEN;
            case SETTLE, APPROVE, RESETTLE -> ClaimStatus.SETTLED;
            case VOID -> ClaimStatus.VOID;
        };
        String reason = request.reason() == null ? "" : request.reason().trim();
        if (taken == ClaimAction.REJECT && reason.isEmpty()) {
            throw new InvalidClaimStatusException("A rejection needs a reason");
        }
        change.set(new ClaimStatusChange(taken, to, request.by() == null ? "" : request.by().trim(),
                taken == ClaimAction.REJECT ? reason : ""));
    }
}
